const deepmind='https://deepmind.google/blog/safety-first-ai-for-autonomous-data-centre-cooling-and-industrial-control/';
const demand='https://cloud.google.com/blog/products/infrastructure/using-demand-response-to-reduce-data-center-power-consumption';
const cloudflare='https://blog.cloudflare.com/post-mortem-on-cloudflare-control-plane-and-analytics-outage/';
const retest='https://blog.cloudflare.com/major-data-center-power-failure-again-cloudflare-code-orange-tested/';
const london='https://status.cloud.google.com/incidents/fmEL9i2fArADKawkZAa2';
const control='d14-coordinating-control-and-work', reliability='d14-maintenance-and-service-reliability';
const s=(storyGroup,id,label,title,explanation,url,objective='D14.2')=>({storyGroup,id,label,title,explanation:[explanation],sources:[url],reference:objective==='D14.2'?control:reliability,objective,pedagogical_role:'case-study'});
export const caseStoryScenes=[
 s('google-cooling','google-cooling','Google: autonomous cooling','Google moved from cooling advice to autonomous control.','Google’s 2016 system recommended cooling actions for operators to implement. Its August 2018 account describes autonomous control under operator supervision. Humans set constraints and can exit autonomous mode; they do not approve every action.',deepmind),
 s('google-cooling','google-cooling-flow','Google: the control loop','Google’s cooling control loop repeats every five minutes.','Every five minutes the supervisory system takes a sensor snapshot, predicts energy and temperature consequences, and selects actions within constraints. Local controls independently verify instructions before implementing them. Operators retain override. The four original publisher diagrams show the sequence in reading order; five minutes is not protective response time.',deepmind),
 s('google-cooling','google-cooling-performance','Google: cooling performance','Autonomous cooling improved with experience.','Google DeepMind’s original plot compares trailing twelve-month AI performance with the historical baseline before AI control. Performance is cooling energy efficiency in kW per ton of cooling; lower energy input for the same cooling output is better. The reported improvement grew from about 12% to about 30% over nine months. This is a cooling-efficiency metric, not a 30% reduction in whole-site electricity. The blue series shows the number of training examples. The original animation is preserved.',deepmind),
 s('google-demand-response','google-demand-response','Google: a grid request','The utility asked Google to reduce demand during busy grid hours.','Google’s October 2023 account describes a day-ahead demand-response pilot at The Dalles, Oregon with Northern Wasco County PUD. Google used computation scheduling to lower demand during specified grid events while preserving urgent service.',demand),
 s('google-demand-response','google-demand-response-workloads','Google: what can wait?','Google deferred background processing while serving live requests.','The operator names YouTube video processing and adding words to Google Translate as non-urgent background work. Forecast grid events trigger hour-by-hour computing limits. Eligible work shifts to later hours or locations; Google Search, Maps and YouTube services remain available. The following slide uses a separate illustrative schedule to explain the mechanism. Google’s account does not disclose that example’s power values or a measured LLM-training benchmark.',demand),
 s('cloudflare','cloudflare-pdx','Cloudflare: outage and dependency','A single point of failure disrupted Cloudflare’s three-site cluster.','On November 2, 2023 a whole Portland facility lost power. Its control-plane and analytics dependencies failed, disrupting the dashboard, API and analytics. Cloudflare’s own reconstruction of the initial power chain includes uncertainty; this case follows the verified service and dependency failures. Kafka and ClickHouse were only available at PDX-04, and high-availability services depended on them. Earlier exercises removed other facilities and the high-availability portion of PDX-04, but never all of PDX-04. The figure contrasts this tested boundary with the actual whole-facility failure, without claiming a complete production topology.',cloudflare,'D14.4'),
 s('cloudflare','cloudflare-facility-test','Cloudflare: fix and test','Cloudflare expanded failover capacity and tested a whole-site loss.','Code Orange included service changes and additional network and server capacity. A February 2024 cut test exercised the full facility boundary and exposed a further Logpush issue; Amsterdam failover preserved delivery during that exercise. The team fixed the uncovered gap before the next real event.',retest,'D14.5'),
 s('cloudflare','cloudflare-retest','Cloudflare: the repeat failure','The next power failure saw APIs and dashboards recover in seven minutes.','On March 26, 2024 the same facility lost power at 14:58 UTC; API and dashboard service was normal by 15:05 without human intervention. Analytics recovered later. This endpoint is not total facility restart or universal seven-minute recovery.',retest,'D14.5'),
 {...s('london','london-cooling-quote','London: Google’s incident report','Google’s account of the London cooling failure.','Google Cloud’s final incident report, published July 29, 2022, attributes the July 19 outage to simultaneous redundant-cooling failures during extreme outdoor heat.',london,'D14.4'),imageOnly:true},
 s('london','london-recovery','London: heat and cooling failure','Extreme heat and cooling failures forced Google to shut down servers.','On July 19, 2022, simultaneous redundant-cooling failures during extreme heat affected part of europe-west2-a in London. Google powered down servers to protect equipment. Only part of the zone was physically affected, but an initial routing change avoided all three regional zones and widened some service impacts.',london,'D14.4'),
 s('london','london-recovery-timeline','London: restarting the service','Restoring cooling began a further fourteen hours of service recovery.','Final July 29 incident-summary times, all PDT: servers powered down July 19 10:05; cooling repaired July 19 14:13; initial cloud-service restoration milestone July 20 04:28. Restart sequencing and service-state recovery continued after cooling repair. Residual issues lasted longer; these are not identical customer downtime measurements.',london,'D14.4')
];
const credit=(label,url)=>`<p class="os-credit"><a href="${url}" target="_blank" rel="noreferrer">${label}</a></p>`;
const photo=(asset,alt,url,label)=>`<figure class="os-photo"><img src="../assets/references/${asset}" alt="${alt}"><figcaption><a href="${url}" target="_blank" rel="noreferrer">${label}</a></figcaption></figure>`;
const item=(label,value)=>`<div class="os-fact"><span>${label}</span><strong>${value}</strong></div>`;
const node=(heading,body,tone='')=>`<section class="os-node ${tone}"><h2>${heading}</h2><p>${body}</p></section>`;
export function caseStoryVisual(id){
 switch(id){
 case 'google-cooling':return `<div class="os-split">${photo('operations-google-cooling-facility.jpg','Google data center pictured in the 2018 DeepMind cooling-control account.',deepmind,'Google DeepMind · August 2018')}<div class="os-facts">${item('2016','AI advises; operator acts')}${item('2018','AI controls cooling')}<p class="os-key">Operators set limits and retain override.</p></div></div>`;
 case 'google-cooling-flow':return `<div class="os-cooling-loop"><div class="os-control-grid">${[
  ['operations-google-sensor-snapshot.jpg','1 · Read sensors','Step 1: every five minutes, cloud AI receives a snapshot from thousands of cooling sensors.'],
  ['operations-google-prediction.jpg','2 · Predict outcomes','Step 2: neural networks predict energy efficiency and temperature for proposed actions.'],
  ['operations-google-action-selection.jpg','3 · Choose within limits','Step 3: AI selects actions within safety constraints to minimize future energy consumption.'],
  ['operations-google-local-verification.jpg','4 · Verify locally, then act','Step 4: local controls verify the proposed actions against their own safety constraints before implementation.']
 ].map(([asset,label,alt])=>`<figure><figcaption>${label}</figcaption><a href="../assets/references/${asset}" target="_blank" rel="noreferrer" aria-label="View full-size original: ${label}"><img src="../assets/references/${asset}" alt="${alt}" width="950" height="534"></a></figure>`).join('')}</div>${credit('Google DeepMind · original control diagrams · August 2018',deepmind)}</div>`;
 case 'google-cooling-performance':return `<div class="os-performance"><figure><img src="../assets/references/operations-google-cooling-performance.gif" alt="Google DeepMind plot from September 2017 to July 2018: trailing twelve-month cooling performance improves from about 12% to about 30% below the historical energy-per-cooling baseline, while training data grows from about 12 million to over 80 million examples." width="1280" height="745"><figcaption>Cooling energy per ton of cooling: ~12% → ~30% improvement versus the pre-AI baseline.</figcaption></figure>${credit('Google DeepMind · original performance plot · August 2018',deepmind)}</div>`;
 case 'google-demand-response':return `<div class="os-split">${photo('storage-google-dalles-repair.jpg','Technician working at Google’s The Dalles data center.',demand,'Google · The Dalles')}<div class="os-facts">${item('The Dalles, Oregon · 2023','Day-ahead demand response')}${item('Utility partner','Northern Wasco County PUD')}<p class="os-key">Schedule less computing during a forecast grid constraint.</p></div></div>`;
 case 'google-demand-response-workloads':return `<div class="os-stack"><div class="os-two">${node('Keep serving','Search requests<br>Maps queries<br>Video playback','good')}${node('Defer eligible background work','Video processing<br>Translation updates','warm')}</div><div class="os-sequence"><span>Grid notice</span><b>→</b><span>Hourly compute limits</span><b>→</b><span>Catch up later</span></div>${credit('Google Cloud · demand response, October 2023',demand)}</div>`;
 case 'cloudflare-pdx':return `<div class="os-stack os-cloudflare-incident"><p class="os-dateline">Portland · 2 November 2023 · facility power loss</p><div class="os-service-impact"><h2>Core services</h2><p>Dashboard · API · analytics <strong>Disrupted</strong></p></div><div class="os-sites"><section><h2>PDX-04</h2><div class="os-tested">HA services<br><small>Previously tested offline</small></div><div class="os-single">Kafka + ClickHouse<br><small>Only here</small></div></section><section><h2>Site B</h2><div class="os-tested">HA services</div><span class="os-depend-arrow">← depends on PDX-04</span></section><section><h2>Site C</h2><div class="os-tested">HA services</div><span class="os-depend-arrow">← depends on PDX-04</span></section></div><p class="os-key">The real outage removed the entire PDX-04 facility.</p>${credit('Cloudflare · November 2023 postmortem',cloudflare)}</div>`;
 case 'cloudflare-facility-test':return `<div class="os-stack"><p class="os-dateline">Code Orange · November 2023 → February 2024</p><div class="os-three">${node('Expand capacity','More servers and network capacity')}${node('Fix failover','Remove single-site service dependencies')}${node('Test the facility loss','Find and repair remaining gaps','good')}</div>${credit('Cloudflare · Code Orange follow-up',retest)}</div>`;
 case 'cloudflare-retest':return `<div class="os-stack"><p class="os-dateline">26 March 2024 · the same facility loses power again</p><div class="os-recovery-pair">${item('14:58 UTC','Power lost')}<span class="os-duration">7 min →</span>${item('15:05 UTC','API + dashboard normal')}</div><div class="os-two os-outcome"><p>No human intervention for API/dashboard recovery</p><p>Analytics recovered later that day</p></div>${credit('Cloudflare · April 2024 follow-up',retest)}</div>`;
 case 'london-cooling-quote':return `<figure class="os-quote"><blockquote cite="${london}">“One of the data centers that hosts zone europe-west2-a could not maintain a safe operating temperature due to a simultaneous failure of multiple, redundant cooling systems combined with the extraordinarily high outside temperatures.”</blockquote><figcaption class="os-credit"><a href="${london}" target="_blank" rel="noreferrer">Google Cloud · Incident Report · July 29, 2022</a></figcaption></figure>`;
 case 'london-recovery':return `<div class="os-stack"><p class="os-dateline">Google Cloud · London · 19 July 2022</p><div class="os-sequence os-london-sequence"><span>Extreme heat</span><b>+</b><span>Redundant cooling fails</span><b>→</b><span>Protective shutdown</span></div><div class="os-region"><span>europe-west2-a<strong>Partly shut down</strong></span><span>europe-west2-b<strong>Other zone</strong></span><span>europe-west2-c<strong>Other zone</strong></span></div><p class="os-key">Some virtual machines stopped; dependent services also failed.</p>${credit('Google Cloud · final incident report',london)}</div>`;
 case 'london-recovery-timeline':return `<div class="os-stack"><div class="os-restoration"><section><span>19 July · 10:05</span><h2>Servers shut down</h2></section><div class="os-interval warm"><b>4 h 08 min</b><span>Cooling repair</span></div><section><span>19 July · 14:13</span><h2>Cooling restored</h2></section><div class="os-interval"><b>14 h 15 min</b><span>Service recovery</span></div><section><span>20 July · 04:28</span><h2>Initial restoration</h2></section></div><p class="os-key">Restart servers → restore service dependencies → reconcile state</p>${credit('Google Cloud · final summary · all timestamps PDT; residual issues lasted longer',london)}</div>`;
 default:return null;
 }
}
